"""Articulated machines built from explicit local-frame joints, never frozen poses."""
from .production import *
D='robotics'
def p(k,n,f,s,**kw):return dp('robot.'+k,n,'mech',f,s,D,theme='robotics',material=kw.pop('material','mat.metal'),**kw)
def a(k,n,items,**kw):return da('robot-'+k,n,'mech',items,D,theme='robotics',**kw)
def ip(k):return 'exp.robot.'+k
def ia(k):return 'exp-robot-'+k

