    p('foot','机械足底 · 分趾接触垫与踝座',[formbox(.32,.075,.42,'charcoal',x=-.02,z=.065),formbox(.32,.065,.35,'steel',x=-.02,y=.075,z=.02),ring(.085,.025,.18,'steel',position=[0,.21,0],rotation=[0,0,90]),*[formbox(.135,.08,.11,'linen',x=x,y=.035,z=.29) for x in [-.105,.065]]],[.34,.3,.51],ports=[socket('ground',[0,0,0],[0,-1,0],'arch.floor.1m.v1',tangent=[1,0,0])],collision=box_collision([.34,.14,.51],[0,.07,.075]))
