    a('tool_array','可换末端工具组 · 夹爪、钻具与传感器',[ai('gripper',ia('gripper'),[-.60,0,0]),pi('drill','exp.industry.drill_head',[0,0,0]),pi('optic',ip('sensor'),[.6,.35,0]),ai('linear',ia('linear_drive'),[1.2,.1,0])],metadata={'purpose':'tool inspection layout, not an automatic tool changer'})
